import sys

def main():
    # Initialize HashMap with product details
    inventory = {
        "Laptop": 50000,
        "Mobile": 20000,
        "Tablet": 15000,
        "Monitor": 10000
    }

    # Read product name from input
    product = sys.stdin.readline().strip()

    # Search for the product and display result
    if product in inventory:
        print(f"Price: {inventory[product]}")
    else:
        print("Product not found")

if __name__ == "__main__":
    main()
